package com.lasheel.smartpantry;
import android.app.*;import android.view.*;import android.widget.*;
public class UI { static LinearLayout page(Activity a,String title){LinearLayout l=new LinearLayout(a);l.setOrientation(1);l.setPadding(22,22,22,22);ScrollView s=new ScrollView(a);s.addView(l);a.setContentView(s);TextView t=new TextView(a);t.setText(title);t.setTextSize(25);l.addView(t);return l;} static Button button(Activity a,LinearLayout l,String label,Runnable r){Button b=new Button(a);b.setText(label);l.addView(b);b.setOnClickListener(v->r.run());return b;} static TextView text(Activity a,LinearLayout l,String text){TextView t=new TextView(a);t.setText(text);t.setTextSize(17);t.setPadding(5,12,5,12);l.addView(t);return t;} static EditText input(Activity a,LinearLayout l,String hint,String val){EditText e=new EditText(a);e.setHint(hint);e.setText(val);l.addView(e);return e;} static void msg(Activity a,String s){Toast.makeText(a,s,Toast.LENGTH_LONG).show();} }